for (const [key, translations] of Object.entries(WORKSPACE_TRANSLATIONS)) {
  if (translations.nb) NB[key] = translations.nb;
  if (translations.ar) AR[key] = translations.ar;
  if (translations.es) ES[key] = translations.es;
  if (translations.fr) FR[key] = translations.fr;
  if (translations.de) DE[key] = translations.de;
}

export function LocalizedText({ en, nb, ar }: { en: string; nb?: string; ar?: string }) {
  const [language, setLanguage] = useState<AppLanguage>("en");
  useEffect(() => {
    let saved: string | null = null;
    try { saved = window.localStorage.getItem("zavqera-language"); } catch { /* storage may be blocked */ }
    const cookie = document.cookie.split("; ").find((part) => part.startsWith("zavqera-language="))?.split("=")[1];
    const candidate = saved || cookie || navigator.language.toLowerCase().split("-")[0];
    setLanguage(["ar", "nb", "es", "fr", "de"].includes(candidate) ? candidate as AppLanguage : "en");
    const onLanguageChange = (event: Event) => {
      const value = (event as CustomEvent<string>).detail;
      setLanguage(["ar", "nb", "es", "fr", "de"].includes(value) ? value as AppLanguage : "en");
    };
    window.addEventListener("zavqera-language-change", onLanguageChange);
    return () => window.removeEventListener("zavqera-language-change", onLanguageChange);
  }, []);
  return <>{language === "ar" ? (ar ?? AR[en] ?? en) : language === "nb" ? (nb ?? NB[en] ?? en) : language === "es" ? (ES[en] ?? en) : language === "fr" ? (FR[en] ?? en) : language === "de" ? (DE[en] ?? en) : en}</>;
}
